// Synthetic localhost-only CA and server key, never imported by product lib.
// Root trusted only in this test context; leaf has serverAuth/SAN and 365-day
// validity (regenerate after 2027-10-27). No production trust overrides.
import 'dart:convert';
import 'dart:io';

SecurityContext fixtureServerContext({bool? usePkcs12}) {
  // The pinned engine's BoringSSL loader needs the certificate chain set
  // separately even when the private key is read from a PKCS12 bundle.
  final context = SecurityContext()
    ..useCertificateChainBytes(utf8.encode(fixtureCertificate));
  if (usePkcs12 ?? Platform.isIOS) {
    // Also exercised explicitly by the host TLS test, not only on devices.
    context.usePrivateKeyBytes(
      base64Decode(fixturePkcs12),
      password: 'synthetic-fixture-only',
    );
  } else {
    context.usePrivateKeyBytes(utf8.encode(fixturePrivateKey));
  }
  return context;
}

// The pinned engine parses PEM anchors on iOS too; raw DER is rejected by
// its BoringSSL parser (BAD_PKCS12_DATA). Keep chain verification enabled.
SecurityContext fixtureClientContext() =>
    SecurityContext()
      ..setTrustedCertificatesBytes(utf8.encode(fixtureRootCertificate));

